import {all, any, bool, nat, not, oneOf, rule, when} from 'gdp-wired'

export const initializableMockRule = rule("InitializableMock")
  .params({W256$0: nat, msg_sender: nat})
  .inputs({method: oneOf('initialize', 'initializeNested', 'initializeWithX', 'nonInitializable'), msg_sender_: nat, msg_value: nat, x_: nat})
  .state({balance: 0, W256$: ({W256$0}) => W256$0, initialized: bool.from(false), initializing: bool.from(false), initializerRan: bool.from(false), x: 0})
  .pre(({W256$0, msg_sender}) => all(all(W256$0.atLeast(2), msg_sender.eq(0).not()), msg_sender.atLeast(0)))
  .assume(({method, msg_sender_, msg_value, W256$, x_, initializing, initialized, balance}) => all(method.is('initialize').implies(msg_sender_.atLeast(0)), method.is('initializeNested').implies(msg_sender_.atLeast(0)), method.is('initializeWithX').implies(msg_sender_.atLeast(0)), method.is('initializeWithX').implies(all(msg_value.atLeast(0), msg_value.lt(W256$))), method.is('initializeWithX').implies(all(x_.atLeast(0), x_.lt(W256$))), method.is('nonInitializable').implies(msg_sender_.atLeast(0)), method.is('nonInitializable').implies(all(msg_value.atLeast(0), msg_value.lt(W256$))), method.is('nonInitializable').implies(all(x_.atLeast(0), x_.lt(W256$))), method.is('initialize').implies(all(method.is('initialize').implies(msg_sender_.eq(0).not()), not(all(method.is('initialize'), msg_sender_.eq(0).not(), not(initializing), initialized)))), method.is('initializeNested').implies(all(method.is('initializeNested').implies(msg_sender_.eq(0).not()), not(all(method.is('initializeNested'), msg_sender_.eq(0).not(), not(initializing), initialized)))), method.is('initializeWithX').implies(all(method.is('initializeWithX').implies(msg_sender_.eq(0).not()), not(all(method.is('initializeWithX'), msg_sender_.eq(0).not(), W256$.atMost(balance.plus(msg_value)))), not(all(method.is('initializeWithX'), msg_sender_.eq(0).not(), balance.plus(msg_value).lt(W256$), not(initializing), initialized)))), method.is('nonInitializable').implies(all(method.is('nonInitializable').implies(msg_sender_.eq(0).not()), not(all(method.is('nonInitializable'), msg_sender_.eq(0).not(), W256$.atMost(balance.plus(msg_value))))))))
  .step(({method, balance, msg_value, initializing, initialized, initializerRan, x, x_}) => {
    const t1 = method.is('initialize')
    const t2 = method.is('initializeNested')
    const t3 = any(not(initializing), initialized)
    return {balance: when(t1, balance, when(t2, balance, balance.plus(msg_value))), initialized: when(t1, t3, when(t2, t3, when(method.is('initializeWithX'), t3, initialized))), initializerRan: any(t1, t2, initializerRan), x: when(t1, x, when(t2, x, x_))}
  })

// What every state of the code is: a law about every state is about the code's with these beside it.
export const initializableMockInvariants = [initializableMockRule.law("balance within its type's range", ({balance, W256$}) => balance.lt(W256$)), initializableMockRule.law("x within its type's range", ({x, W256$}) => x.lt(W256$))]

